#include <stdio.h>
#include <stdlib.h>

int minCostClimbingStairs(int* cost, int costSize) {
    int next1 = 0, next2 = 0;
    for (int i = costSize - 1; i >= 0; --i) {
        int current = cost[i] + (next1 < next2 ? next1 : next2);
        next2 = next1;
        next1 = current;
    }
    return next1 < next2 ? next1 : next2;
}

