class Solution {
public:
    int minCostClimbingStairs(vector<int>& cost) {
        int next1 = 0, next2 = 0;
        for (int i = (int)cost.size() - 1; i >= 0; --i) {
            int current = cost[i] + min(next1, next2);
            next2 = next1;
            next1 = current;
        }
        return min(next1, next2);
    }
